-- Every published lesson of a Reading topic with a final test now offers at least two practice sets.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM lessons l JOIN topics t ON t.id = l.topic_id
               WHERE l.status = 'PUBLISHED' AND t.skill = 'READING'
                 AND EXISTS (SELECT 1 FROM content_packages tp
                             WHERE tp.topic_id = l.topic_id AND tp.package_type = 'TOPIC_TEST' AND tp.status = 'PUBLISHED')
                 AND (SELECT count(*) FROM content_packages p
                      WHERE p.lesson_id = l.id AND p.package_type = 'PRACTICE_SET' AND p.status = 'PUBLISHED') < 2) THEN
        RAISE EXCEPTION 'Every published Reading lesson of a topic with a final test needs two practice sets';
    END IF;
END $$;
