INSERT INTO content_assets (id, asset_type, text_content, validation_status) VALUES ('27000000-0000-4000-8000-050000000002', 'PASSAGE', 'A. The cactus stores water in its thick stem. Its leaves have become sharp spines, which lose almost no moisture. In short, every part of the cactus is designed to survive without rain.
