INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, hint, status) VALUES
    ('27000000-0000-4000-8000-070000000004', '27000000-0000-4000-8000-060000000004', 1, 'Which sentence is the topic sentence of paragraph A?', '[{"optionKey": "A", "content": "The cactus stores water in its thick stem.", "sortOrder": 1}, {"optionKey": "B", "content": "Its leaves have become sharp spines, which lose almost no moisture.", "sortOrder": 2}, {"optionKey": "C", "content": "In short, every part of the cactus is designed to survive without rain.", "sortOrder": 3}]'::jsonb, '{"type": "CHOICE", "correct": "C"}'::jsonb, 1, 'Câu chủ đề không phải lúc nào cũng ở đầu đoạn: "In short" tóm lại ý chung, hai câu trước là chi tiết về thân và lá.', 'Câu chủ đề có thể nằm cuối đoạn. Câu nào khái quát được cả đoạn?', 'PUBLISHED');
