INSERT INTO content_assets (id, asset_type, text_content, validation_status) VALUES ('27000000-0000-4000-8000-050000000003', 'PASSAGE', 'A. Sleep plays an important role in memory. During deep sleep, the brain replays what we learned during the day and stores it for the long term. In one study, students who slept after a lesson recalled 20% more the next morning.
