    ('27000000-0000-4000-8000-070000000016', '27000000-0000-4000-8000-060000000016', 1, 'Passage: "The library lends up to five books at a time for three weeks." Statement: "Members may borrow six books at once."', '[{"optionKey": "TRUE", "content": "TRUE", "sortOrder": 1}, {"optionKey": "FALSE", "content": "FALSE", "sortOrder": 2}, {"optionKey": "NOT_GIVEN", "content": "NOT GIVEN", "sortOrder": 3}]'::jsonb, '{"type": "CHOICE", "correct": "FALSE"}'::jsonb, 1, 'Tối đa năm cuốn mỗi lần; sáu cuốn mâu thuẫn trực tiếp: FALSE.', 'So con số trong câu khẳng định với con số trong đoạn văn.', 'PUBLISHED');
