    ('27000000-0000-4000-8000-070000000017', '27000000-0000-4000-8000-060000000017', 1, 'Passage: "The train to the airport leaves every twenty minutes from platform 4." Statement: "The airport train is usually crowded."', '[{"optionKey": "TRUE", "content": "TRUE", "sortOrder": 1}, {"optionKey": "FALSE", "content": "FALSE", "sortOrder": 2}, {"optionKey": "NOT_GIVEN", "content": "NOT GIVEN", "sortOrder": 3}]'::jsonb, '{"type": "CHOICE", "correct": "NOT_GIVEN"}'::jsonb, 1, 'Đoạn văn chỉ nói tần suất và sân ga, không nói tàu có đông hay không: NOT GIVEN.', 'Đoạn văn có nhắc gì tới số lượng hành khách không?', 'PUBLISHED');
