    ('27000000-0000-4000-8000-070000000018', '27000000-0000-4000-8000-060000000018', 1, 'Passage: "The course is taught entirely online, so students never need to visit the campus." Statement: "Students can complete the course without going to the campus."', '[{"optionKey": "TRUE", "content": "TRUE", "sortOrder": 1}, {"optionKey": "FALSE", "content": "FALSE", "sortOrder": 2}, {"optionKey": "NOT_GIVEN", "content": "NOT GIVEN", "sortOrder": 3}]'::jsonb, '{"type": "CHOICE", "correct": "TRUE"}'::jsonb, 1, '"never need to visit the campus" cùng nghĩa với hoàn thành khóa mà không cần tới trường: TRUE.', 'Diễn đạt lại câu khẳng định, rồi tìm câu cùng nghĩa trong đoạn văn.', 'PUBLISHED');
