    ('27000000-0000-4000-8000-070000000021', '27000000-0000-4000-8000-060000000021', 1, 'Passage: "The factory closed in 2010 because demand for its products fell." Statement: "The factory closed because of a fire."', '[{"optionKey": "TRUE", "content": "TRUE", "sortOrder": 1}, {"optionKey": "FALSE", "content": "FALSE", "sortOrder": 2}, {"optionKey": "NOT_GIVEN", "content": "NOT GIVEN", "sortOrder": 3}]'::jsonb, '{"type": "CHOICE", "correct": "FALSE"}'::jsonb, 1, 'Đoạn văn nêu rõ lý do là nhu cầu giảm, mâu thuẫn với lý do hỏa hoạn: FALSE.', 'Đoạn văn có nêu lý do đóng cửa không? Nếu có, lý do đó có khớp không?', 'PUBLISHED');
