INSERT INTO content_assets (id, asset_type, text_content, validation_status) VALUES ('27000000-0000-4000-8000-050000000012', 'PASSAGE', 'Rooftop farms are spreading across New York. The largest, in Brooklyn, covers about one hectare and produces over 20,000 kilograms of vegetables a year. Most of the food is sold to local restaurants. The farm also runs classes for school groups, although these are only offered in the summer months.', 'VALID');
