INSERT INTO content_assets (id, asset_type, text_content, validation_status) VALUES ('27000000-0000-4000-8000-050000000014', 'PASSAGE', 'Glass is made by heating sand to about 1,700 degrees Celsius. To lower this temperature, makers add soda ash, which saves a great deal of fuel. The liquid glass is then shaped by blowing air into it through a long metal pipe. Finally, it is cooled slowly in a special oven so that it does not crack.', 'VALID');
